/** City stories written from the pre-existing Nexus canon, not from the old
 * administrative contracts. This is presentation/interaction data only.
 * Mission, step and choice keys deliberately retain their saved identifiers.
 * The integration owns proximity, operation receipts and visible prop states;
 * an old completed step must not fabricate a newly performed intervention.
 * sourceRefs describe the established character/world foundations. The local
 * incidents below are new side stories and do not complete campaign chapters. */
const t = (fr, en) => ({ fr, en });
const say = (fr, en, dialogueFr, dialogueEn) => ({
  text: t(fr, en), ...(dialogueFr ? { dialogue: t(dialogueFr, dialogueEn) } : {})
});
const work = (kind, propFr, propEn, actionFr, actionEn, doneFr, doneEn, dialogueFr, dialogueEn) => ({
  ...say(actionFr, actionEn, dialogueFr, dialogueEn), finding: t(doneFr, doneEn),
  operation: { kind, label: t(actionFr, actionEn), propName: t(propFr, propEn), completedText: t(doneFr, doneEn) }
});
const answer = (fr, en, resultFr, resultEn) => ({ label: t(fr, en), result: t(resultFr, resultEn) });
const choose = (fr, en, choices) => ({ text: t(fr, en), choices });
const fork = (field, routes) => ({ ...Object.values(routes)[0], [field]: routes });
const foundations = heroId => [
  'src/game/lore.js#CORE_CODEX_ENTRIES',
  ...(heroId === 'arca_mirelle'
    ? ['src/game/heroes.js#arca_mirelle', 'src/game/ocCampaign.js#OC_CAMPAIGN_MISSIONS']
    : [`src/game/characterPlaques.js#${heroId}`])
];
const quest = (heroId, title, premise, request, location, steps, sourceRefs = []) => ({
  title: t(...title), premise: t(...premise), request: t(...request), location: t(...location),
  sourceRefs: [...foundations(heroId), ...sourceRefs], steps
});

export const MOSAIC_CHARACTER_STORIES = Object.freeze({
  'city-anchor-signature-v1': quest('player_anchor',
    ['La lumière connaît mon nom', 'The light knows my name'],
    ['Une balise de l’Atrium hésite entre deux échos de ta présence. À chaque hésitation, son faisceau de retour s’éteint. La remettre en service ne doit pas coûter ton identité.', 'An Atrium beacon cannot distinguish two echoes of your presence. Its return light goes dark each time it hesitates. Bringing it back must not cost you your identity.'],
    ['Quand je passe devant cette lumière, elle m’appelle puis m’oublie. Je veux pouvoir rentrer ici sans devenir quelqu’un d’autre.', 'When I pass this light, it calls to me, then forgets me. I want to come home without becoming someone else.'],
    ['Atrium Nexus — station de la Bobine d’Ancre', 'Nexus Atrium — Anchor Coil station'], {
      'inspect-nexus_anchor_coil': work('repair', 'bobine d’essai', 'test coil', 'Recaler la bobine sur ta présence.', 'Tune the coil to your presence.', 'La bobine tient ta signature sans en effacer l’origine.', 'The coil holds your signature without erasing its origin.'),
      'inspect-arca_signal_lens': work('scan', 'lentille de la balise', 'beacon lens', 'Séparer les deux échos dans la lentille.', 'Separate the two echoes through the lens.', 'Deux échos reviennent de la même personne. Le plus lumineux n’est pas une autre Ancre.', 'Two echoes return from the same person. The brighter one is not another Anchor.'),
      resolution: choose('Que laisseras-tu à la balise ?', 'What will you leave with the beacon?', {
        'retain-origin': answer('Garder mon origine et les deux échos.', 'Keep my origin and both echoes.', 'La balise peut te reconnaître sans choisir une version de toi à supprimer.', 'The beacon can recognize you without choosing a version of you to erase.'),
        'ask-review': answer('Laisser les échos séparés et demander de l’aide.', 'Keep the echoes apart and ask for help.', 'La fusion reste arrêtée. Tu gardes ton identité pendant qu’A.R.C.A. reprend le réglage.', 'Merging stays stopped. You keep your identity while A.R.C.A. checks the tuning.'),
        'replace-origin': answer('Laisser le signal le plus fort me remplacer.', 'Let the strongest signal replace me.', 'Être plus facile à suivre ne donne pas à un écho le droit de vivre à ta place.', 'Being easier to track does not give an echo the right to live in your place.')
      }),
      report: say('Revenir près de l’ancre de l’Atrium.', 'Return to the Atrium anchor.', 'Je suis encore là. Le chemin du retour doit partir de cette personne-là.', 'I am still here. The way home has to start with that person.')
    }, ['src/game/ocCampaign.js#8801']),

  'city-mirelle-suture-v1': quest('arca_mirelle',
    ['Deux voix dans le noir', 'Two voices in the dark'],
    ['Le relais de secours du Nexus superpose deux appels. Mirelle entend quelqu’un demander de l’aide, mais la répétition empêche de savoir quel canal lui répond.', 'The Nexus emergency relay is overlapping two calls. Mirelle can hear someone asking for help, but the repetition makes it impossible to tell which channel answers.'],
    ['Écoute : ce n’est pas la même respiration. Si je coupe la mauvaise voix, quelqu’un restera seul. Viens tenir la boucle pendant que je les sépare.', 'Listen: the breathing is different. If I cut the wrong voice, someone will be left alone. Hold the loop with me while I separate them.'],
    ['Quartier Nexus — relais de secours de l’Atrium', 'Nexus district — Atrium emergency relay'], {
      'meet-arca_mirelle': say('Rejoindre Mirelle près du relais.', 'Join Mirelle by the relay.', 'Ne cherche pas la voix la plus nette. Cherche celle qui essaie encore de répondre.', 'Do not look for the clearest voice. Look for the one still trying to answer.'),
      'inspect-nexus_anchor_coil': work('scan', 'bobine de secours', 'backup coil', 'Trouver le raccord de secours sur la bobine.', 'Find the backup connection on the coil.', 'La boucle peut garder les deux voix pendant que le relais est débranché.', 'The loop can hold both voices while the relay is disconnected.'),
      'suture-relay': work('repair', 'relais de secours', 'emergency relay', 'Démêler les fils du relais sans vider sa boucle.', 'Untangle the relay wires without emptying its loop.', 'Deux canaux apparaissent sous la répétition. Les voix sont encore présentes dans la boucle de sauvegarde.', 'Two channels emerge beneath the repetition. Both voices remain in the backup loop.', 'Voilà. Elles étaient emmêlées, pas fausses.', 'There. They were tangled, not false.'),
      resolution: choose('Comment garder le contact ?', 'How will you keep contact?', {
        'separate-traces': answer('Rétablir un canal pour chaque voix.', 'Restore a channel for each voice.', 'Mirelle garde les deux identités distinctes. Chaque voix retrouve son propre canal.', 'Mirelle keeps both identities separate. Each voice has its own channel again.'),
        'isolate-relay': answer('Isoler le relais et garder les voix dans la boucle.', 'Isolate the relay and keep the voices in the loop.', 'Le relais reste coupé. Mirelle veille sur les deux voix en attendant une réparation plus sûre.', 'The relay stays disconnected. Mirelle watches over both voices until a safer repair is possible.'),
        'erase-copy': answer('Effacer la voix qui se répète.', 'Erase the repeating voice.', '« Non. Une panne ne nous dit pas qui mérite de rester. »', '“No. A fault does not tell us who deserves to stay.”')
      }),
      report: say('Ramener la liaison près de l’ancre de l’Atrium.', 'Bring the connection back to the Atrium anchor.', 'Je préfère une voix qui tremble à un silence bien rangé.', 'I would rather hear a trembling voice than a tidy silence.')
    }, ['src/game/mosaicCityRuntime.js#MOSAIC_WELCOME']),

  'city-bastion-tenth-route-v1': quest('arca_bastion',
    ['La grille ne doit plus mentir', 'The gate must not lie again'],
    ['Au Rempart Est, une grille de service s’est bloquée sous une ancienne flèche d’évacuation. Cette flèche désigne encore la dixième route condamnée. Bastion veut dégager le retour vers l’Atrium et dire pourquoi l’autre issue reste fermée.', 'At the East Bulwark, a service gate has jammed beneath an old evacuation arrow. That arrow still points toward the condemned tenth route. Bastion wants to clear the way back to the Atrium and say why the other exit remains closed.'],
    ['J’ai fermé cette route une fois. Je ne laisserai pas une flèche y renvoyer quelqu’un. Aide-moi avec la grille ; pour le reste, je parlerai.', 'I closed that route once. I will not let an arrow send someone there again. Help me with the gate. I will do the talking.'],
    ['Quartier Nexus — poste du Rempart Est', 'Nexus district — East Bulwark post'], {
      'meet-arca_bastion': say('Rejoindre Bastion au poste du Rempart.', 'Join Bastion at the Bulwark post.', 'Ne force pas vers la dixième. La sortie de service revient ici, de notre côté.', 'Do not force it toward the tenth. The service exit comes back here, on our side.'),
      'east-record': work('repair', 'commande de grille', 'gate control', 'Libérer la commande de la grille de service.', 'Free the service gate control.', 'La commande revient en place. La flèche au-dessus désigne pourtant toujours la route condamnée.', 'The control moves back into place. The arrow above it still points at the condemned route.'),
      'route-register': work('secure', 'ancienne flèche d’évacuation', 'old evacuation arrow', 'Masquer la fausse sortie et dégager le retour vers l’Atrium.', 'Cover the false exit and clear the way back to the Atrium.', 'Le retour de service est dégagé. La dixième route reste condamnée ; sa plaque a une ligne dont les noms ont disparu.', 'The service return is clear. The tenth route remains condemned; its plaque has a line whose names have vanished.'),
      resolution: choose('Que dira Bastion à ceux qui suivront la flèche ?', 'What will Bastion tell those who follow the arrow?', {
        'name-debt': answer('Dire ce qui a été condamné et appeler les témoins.', 'Say what was condemned and call for witnesses.', 'Bastion reconnaît sa décision. La dixième route reste nommée, avec une place pour ceux qui pourront rendre leurs noms aux absents.', 'Bastion acknowledges his decision. The tenth route remains named, with room for those who may restore the names of the absent.'),
        'attach-unknowns': answer('Garder la fermeture visible, même sans tous les noms.', 'Keep the closure visible, even without every name.', 'La fermeture et les noms encore inconnus restent visibles. Le silence ne devient pas une version où personne n’a manqué.', 'The closure and the still-unknown names remain visible. Silence does not become a version in which no one was missing.'),
        'perfect-report': answer('Ne parler que des neuf cellules sauvées.', 'Speak only of the nine cells saved.', '« Ne me donne pas une victoire qui les efface une seconde fois. »', '“Do not give me a victory that erases them a second time.”')
      }),
      report: say('Revenir à l’ancre par le passage dégagé.', 'Return to the anchor through the cleared passage.', 'Cette fois, ceux qui passent savent où mène ma protection.', 'This time, those who pass know where my protection leads.')
    }),

  'city-nova-measured-exit-v1': quest('arca_nova',
    ['Le sol a un temps de retard', 'The ground is one beat late'],
    ['Un passage du Nexus se recompose après chaque pulsation. Son entrée semble solide tandis que le bord opposé revient trop tard. Nova cherche un trajet possible sans envoyer quelqu’un sur la foi d’une image parfaite.', 'A Nexus passage reforms after each pulse. Its entrance looks solid while the far edge returns too late. Nova needs a possible route without sending anyone across on the strength of a perfect image.'],
    ['Je peux te montrer quand le sol revient. Je ne peux pas promettre ce qu’il fera derrière toi. Pose une sonde à chaque bord ; ensuite, on choisira.', 'I can show you when the ground returns. I cannot promise what it will do behind you. Put a probe on each edge. Then we choose.'],
    ['Quartier Nexus — balises du passage instable', 'Nexus district — unstable passage beacons'], {
      'meet-arca_nova': say('Rejoindre Nova et son diapason.', 'Join Nova and her resonance tuner.', 'Mon monocle montre des causes, pas des lendemains. Garde les yeux sur les deux bords.', 'My monocle shows causes, not tomorrows. Keep your eyes on both edges.'),
      'inspect-arca_signal_lens': work('scan', 'lentille de phase', 'phase lens', 'Régler la lentille sur la pulsation du passage.', 'Tune the lens to the passage pulse.', 'La lentille distingue la lumière du portail et le retour réel du sol.', 'The lens distinguishes the portal light from the ground actually returning.'),
      'near-reading': work('beacon', 'sonde de départ', 'departure probe', 'Poser la sonde au bord qui tient.', 'Place the probe on the stable edge.', 'La sonde accroche une pulsation et conserve son heure de départ.', 'The probe catches a pulse and keeps its departure time.'),
      'far-reading': work('scan', 'sonde distante', 'far probe', 'Accorder la sonde distante au diapason.', 'Tune the far probe with the resonance tuner.', 'Le signal atteint l’autre bord. La sonde ne donne toujours pas de pulsation de retour.', 'The signal reaches the far edge. The probe still gives no return pulse.', 'Voilà une arrivée. Il nous manque encore le chemin inverse.', 'That is an arrival. We are still missing the way back.'),
      resolution: choose('Comment signaler ce passage ?', 'How will you mark this passage?', {
        'mark-uncertainty': answer('Montrer le trajet possible et avertir : retour inconnu.', 'Show the possible route and warn: return unknown.', 'Nova laisse une possibilité visible avec son risque. Personne n’est envoyé de force de l’autre côté.', 'Nova leaves a possibility visible with its risk. No one is sent across against their will.'),
        'require-return': answer('Attendre une pulsation de retour avant tout départ.', 'Wait for a return pulse before anyone leaves.', 'Le départ reste en attente. Nova garde les sondes en observation au lieu de choisir pour les passants.', 'Departure stays on hold. Nova keeps the probes under observation instead of choosing for those waiting.'),
        'guarantee-future': answer('Annoncer que tout le monde reviendra.', 'Announce that everyone will return.', '« J’ai déjà pris un calcul pour une promesse. Je ne recommencerai pas. »', '“I mistook a calculation for a promise once. I will not do it again.”')
      }),
      report: say('Rentrer à l’ancre par le sol stable.', 'Return to the anchor over stable ground.', 'Une route imparfaite peut être utile. À condition de ne pas cacher ce qui manque.', 'An imperfect route can be useful. As long as we do not hide what is missing.')
    }),

  'city-sable-signed-map-v1': quest('arca_sable',
    ['Les flèches mènent au vide', 'The arrows lead into nothing'],
    ['Les distances ont bougé dans le quartier Nexus. Une carte recopiée sans auteur continue d’envoyer les arrivants vers un passage trop étroit. Sable veut remettre les pieds sur la route avant d’en déplacer les flèches.', 'Distances have shifted in the Nexus district. An unsigned copied map is still sending arrivals toward a passage that has become too narrow. Sable wants boots on the route before she moves its arrows.'],
    ['Une ligne sur du papier ne porte personne. Prends le côté ouest, je garde la longue-vue. Si la route a changé, on la dessinera avec nos pas.', 'A line on paper carries no one. Take the west side; I will keep the scope. If the route has changed, we will draw it with our footsteps.'],
    ['Quartier Nexus — circuit des trois repères', 'Nexus district — three-marker circuit'], {
      'meet-arca_sable': say('Prendre les balises auprès de Sable.', 'Collect the beacons from Sable.', 'Ne signe pas pour me faire plaisir. Signe parce que tu y étais.', 'Do not sign to please me. Sign because you were there.'),
      'map-west': work('beacon', 'repère ouest', 'west marker', 'Fixer une balise au bord du passage ouest.', 'Fasten a beacon to the west passage edge.', 'La première balise marque le bord réellement parcouru, pas celui de la carte copiée.', 'The first beacon marks the edge you actually walked, not the one on the copied map.'),
      'map-east': work('scan', 'jauge du passage est', 'east passage gauge', 'Mesurer la largeur entre les deux bornes est.', 'Measure the width between the two east posts.', 'La largeur ne correspond plus à la carte. Une flèche inchangée conduirait droit au rétrécissement.', 'The width no longer matches the map. An unchanged arrow would lead straight into the narrowing.'),
      'map-return': work('route', 'balise de retour', 'return beacon', 'Rattacher le retour au passage que tu viens de parcourir.', 'Link the return marker to the passage you just walked.', 'Les trois repères forment un retour continu. Ton trajet explique maintenant les écarts de la carte.', 'The three markers form a continuous way back. Your route now accounts for the differences on the map.'),
      resolution: choose('Que laisser aux prochains arrivants ?', 'What will you leave for the next arrivals?', {
        'signed-correction': answer('Corriger les flèches et signer le trajet parcouru.', 'Correct the arrows and sign the route walked.', 'Sable laisse une correction dont vous répondez tous les deux : lieux parcourus, écarts et noms des marcheurs.', 'Sable leaves a correction you both stand behind: the places walked, the differences, and the walkers’ names.'),
        'annotated-original': answer('Garder l’ancienne carte avec le détour mesuré.', 'Keep the old map alongside the measured detour.', 'Le détour et ses auteurs restent lisibles à côté de l’ancienne route. Personne n’a besoin de croire la carte sur parole.', 'The detour and its authors remain visible beside the old route. No one has to take the map on trust.'),
        'anonymous-perfect': answer('Effacer les écarts et laisser une carte sans auteur.', 'Erase the differences and leave an unsigned map.', '« Et quand elle ment à nouveau, qui vient chercher ceux qui l’ont suivie ? »', '“And when it lies again, who comes for the people who followed it?”')
      }),
      report: say('Suivre le retour balisé jusqu’à l’ancre.', 'Follow the marked return to the anchor.', 'Une bonne carte laisse aussi voir les mains qui l’ont faite.', 'A good map also shows the hands that made it.')
    }),

  'city-loom-return-thread-v1': quest('arca_loom',
    ['L’appel derrière le fil', 'The call beyond the thread'],
    ['Un relais renvoie à Loom une voix conservée dans son drone et promet un refuge intact. Elle connaît ce piège : une sortie peut appeler les blessés sans jamais les laisser repartir.', 'A relay sends Loom a voice held in her drone and promises an untouched refuge. She knows the trap: an exit can call to the wounded without ever letting them leave.'],
    ['Cette voix, je la garde depuis la Brèche. Si quelqu’un l’imite, je veux le savoir avant de lui confier les autres. Attache le fil ici. Tu reviens par le même chemin.', 'I have kept that voice since the Breach. If something is imitating it, I want to know before I trust it with the others. Tie the thread here. You come back the same way.'],
    ['Quartier Nexus — ligne de récupération de Loom', 'Nexus district — Loom’s recovery line'], {
      'meet-arca_loom': say('Rejoindre Loom et son drone de suture.', 'Join Loom and her suture drone.', 'Ne promets pas à ces voix leur maison. Pour l’instant, promets-moi ton retour.', 'Do not promise these voices their home. For now, promise me your return.'),
      'thread-departure': work('beacon', 'attache du fil de retour', 'return-thread anchor', 'Fixer le fil de retour au point de départ.', 'Fasten the return thread at the starting point.', 'Le fil tient sur le point de départ. Les voix restent dans le drone de Loom.', 'The thread holds at the starting point. The voices remain in Loom’s drone.'),
      'thread-distance': work('repair', 'relais du fil', 'thread relay', 'Retendre le fil au relais qui porte l’appel.', 'Retension the thread at the relay carrying the call.', 'Le relais rend une tension réelle, mais son appel ne dit pas qui attend au refuge.', 'The relay gives back real tension, but its call does not tell you who is waiting at the shelter.'),
      'thread-home': work('recover', 'extrémité du fil', 'thread end', 'Ramener l’extrémité du fil à Loom.', 'Bring the end of the thread back to Loom.', 'Le fil revient avec sa marque et son usure. Les voix n’ont pas été déplacées.', 'The thread returns with its mark and wear. The voices have not been moved.', 'Te voilà. C’est ça, une issue : elle rend quelqu’un.', 'There you are. That is an exit: it brings someone back.'),
      resolution: choose('Que confier à cette ligne ?', 'What will you entrust to this line?', {
        'verify-thread': answer('Garder ce retour réel, sans promettre le refuge.', 'Keep this real way back without promising the shelter.', 'Loom garde les voix près d’elle. La ligne vérifiée pourra soutenir une récupération locale sans devenir une promesse de monde restauré.', 'Loom keeps the voices with her. The verified line can support local recovery without becoming a promise of a restored world.'),
        'retain-local': answer('Garder les voix ici et n’envoyer que le signal d’essai.', 'Keep the voices here and send only the test signal.', 'Le drone reste leur abri. Seule la mesure du trajet part vers le relais.', 'The drone remains their shelter. Only the route measurement travels to the relay.'),
        'send-unverified': answer('Envoyer les voix vers le refuge qui les appelle.', 'Send the voices to the shelter calling them.', '« Le fil revient. Ça ne veut pas dire qu’il y a quelqu’un pour les accueillir. »', '“The thread comes back. That does not mean anyone is there to receive them.”')
      }),
      report: say('Rentrer à l’ancre sans couper la ligne de Loom.', 'Return to the anchor without cutting Loom’s line.', 'On n’a pas retrouvé leur monde. On a gardé une façon de revenir. C’est déjà quelque chose de vrai.', 'We did not find their world. We kept a way back. That is something real.')
    }),

  'city-marrow-distinct-choices-v1': quest('arca_marrow',
    ['La même voix, deux vies', 'One voice, two lives'],
    ['Un sceau retient deux empreintes conscientes sous le même visage. Sa commande propose d’en effacer une pour libérer l’autre. Marrow refuse de tirer sa lame avant d’avoir entendu ce que chacune veut devenir.', 'A seal holds two conscious imprints behind the same face. Its control offers to erase one to release the other. Marrow refuses to draw his blade before hearing what each wants to become.'],
    ['J’ai déjà cru qu’un visage suffisait. Une personne en est morte. Garde ta main loin de la commande rouge ; on va les écouter, toutes les deux.', 'I once thought a face was enough. Someone died for it. Keep your hand away from the red control. We are going to listen to both of them.'],
    ['Quartier Nexus — deux bornes du sceau de fracture', 'Nexus district — twin fracture-seal posts'], {
      'meet-arca_marrow': say('Rejoindre Marrow devant le sceau.', 'Join Marrow at the seal.', 'Ma lame peut couper ce lien. Elle ne peut pas décider qui mérite d’exister.', 'My blade can cut this bond. It cannot decide who deserves to exist.'),
      'first-imprint': work('secure', 'première attache du sceau', 'first seal clamp', 'Dégager le canal de la première empreinte.', 'Clear the first imprint’s channel.', 'La première empreinte retrouve sa voix : elle veut garder son nom et ses souvenirs.', 'The first imprint regains a voice: they want to keep their name and memories.'),
      'second-imprint': work('secure', 'seconde attache du sceau', 'second seal clamp', 'Dégager le second canal sans écraser le premier.', 'Clear the second channel without overwriting the first.', 'La seconde empreinte reconnaît des souvenirs communs. Elle demande une place à elle, pas celle de l’autre.', 'The second imprint recognizes shared memories. They ask for a place of their own, not the other’s place.', 'Tu as entendu ? Une mémoire commune. Deux demandes différentes.', 'Did you hear? Shared memory. Two different requests.'),
      resolution: choose('Comment les laisser répondre ?', 'How will you let them answer?', {
        'separate-testimony': answer('Garder deux canaux pour deux personnes.', 'Keep two channels for two people.', 'Leurs paroles restent séparées. Aucune ressemblance ne devient une condamnation.', 'Their words remain separate. Resemblance does not become a sentence.'),
        'request-dialogue': answer('Leur laisser le temps de se parler.', 'Give them time to speak to each other.', 'Marrow suspend l’accusation de remplacement. Les deux empreintes peuvent parler sans être forcées de choisir laquelle disparaît.', 'Marrow suspends the accusation of replacement. Both imprints can speak without being forced to decide which one disappears.'),
        'erase-double': answer('Effacer la seconde pour simplifier le sceau.', 'Erase the second to simplify the seal.', '« Non. Je connais déjà la fin de cette facilité-là. »', '“No. I already know how that easy choice ends.”')
      }),
      'return-marrow': say('Retourner auprès de Marrow avec les deux réponses.', 'Return to Marrow with both answers.', 'Je n’ai pas besoin qu’elles me pardonnent. J’ai besoin de ne pas recommencer.', 'I do not need them to forgive me. I need not to do it again.'),
      report: say('Rejoindre l’ancre en laissant les deux canaux ouverts à la parole.', 'Reach the anchor while leaving both channels open to speech.')
    }),

  'city-tessera-two-accounts-v1': quest('arca_tessera',
    ['Une chambre pour Tessera', 'A room for Tessera'],
    ['Une projection de la Galerie reconstitue la chambre d’enfance dont Tessera se souvient. Au seuil, elle lui donne le nom de l’agente morte que la Forge voulait remplacer. Tessera veut un endroit où entrer sous son propre nom.', 'A Gallery projection recreates the childhood room Tessera remembers. At the threshold, it gives her the name of the dead agent the Foundry meant her to replace. Tessera wants somewhere she can enter under her own name.'],
    ['Je me souviens de cette fenêtre. Je me souviens aussi d’avoir ouvert les yeux dans la Forge. Aide-moi à garder les deux sans remettre le nom d’une morte sur ma porte.', 'I remember that window. I also remember opening my eyes in the Foundry. Help me keep both without putting a dead woman’s name on my door.'],
    ['Quartier Nexus — projecteurs de souvenirs de la Galerie', 'Nexus district — Gallery memory projectors'], {
      'meet-arca_tessera': say('Rejoindre Tessera près de la projection.', 'Join Tessera beside the projection.', 'Ça ressemble à chez moi. C’est justement pour ça que je ne veux pas lui obéir les yeux fermés.', 'It looks like home. That is exactly why I do not want to obey it with my eyes closed.'),
      'childhood-caption': work('recover', 'fragment du souvenir d’enfance', 'childhood-memory fragment', 'Mettre le souvenir de la fenêtre à l’abri du projecteur.', 'Take the window memory out of the projector’s reach.', 'Le fragment garde le souvenir raconté par Tessera. Il ne la transforme pas en la personne dont le nom ornait la porte.', 'The fragment keeps the memory Tessera described. It does not turn her into the person whose name was on the door.'),
      'foundry-caption': work('secure', 'commande de remplacement de la Forge', 'Foundry replacement control', 'Bloquer la commande qui remplace un souvenir par l’autre.', 'Block the control that replaces one memory with the other.', 'Le souvenir de la Forge reste distinct. La commande voulait supprimer le premier pour rendre la chambre plus simple à reconstruire.', 'The Foundry memory stays separate. The control wanted to delete the first to make the room easier to rebuild.'),
      resolution: choose('Que laisser vivre dans cette chambre ?', 'What will you allow to live in this room?', {
        'parallel-accounts': answer('Garder les deux souvenirs au nom de Tessera.', 'Keep both memories in Tessera’s name.', 'Les deux récits restent côte à côte, sans remplacer l’agente disparue. Tessera garde le nom qu’elle a choisi.', 'Both accounts stay side by side without replacing the lost agent. Tessera keeps the name she chose.'),
        'hold-display': answer('Éteindre la projection et garder les deux fragments.', 'Turn off the projection and keep both fragments.', 'La chambre attendra une forme que Tessera accepte. Aucun de ses souvenirs n’a besoin de disparaître pendant ce temps.', 'The room will wait for a form Tessera accepts. Neither memory needs to disappear in the meantime.'),
        'replace-memory': answer('Garder l’enfance et effacer la Forge.', 'Keep the childhood and erase the Foundry.', '« Même le souvenir qui fait mal fait partie de moi. Tu ne me protèges pas en me coupant en deux. »', '“Even the memory that hurts is part of me. You are not protecting me by cutting me in half.”')
      }),
      report: say('Revenir à l’ancre avec les deux souvenirs conservés.', 'Return to the anchor with both memories kept.', 'Je peux chercher une maison. Je n’ai pas besoin de voler une vie pour y entrer.', 'I can look for a home. I do not need to steal a life to enter it.')
    }),

  'city-quillon-single-receipt-v1': quest('arca_quillon',
    ['Une lampe pour ceux qui attendent', 'A lamp for those waiting'],
    ['La lampe de secours du point d’accueil reste éteinte. La clé Q-17 nécessaire à son raccord apparaît sur deux reçus de livraison. Quillon sait comment une écriture en double peut finir par faire payer quelqu’un qui n’est plus là.', 'The reception point’s emergency lamp stays dark. The Q-17 key needed for its connection appears on two delivery slips. Quillon knows how a duplicated entry can end with someone absent paying the price.'],
    ['Il leur faut de la lumière, pas une dette de plus. J’ai vu passer cette clé. Aide-moi à la retrouver ; ensuite, je répondrai de la mauvaise ligne.', 'They need light, not another debt. I saw that key pass through. Help me find it. Then I will answer for the bad entry.'],
    ['Quartier Nexus — accueil et chariot de la Galerie', 'Nexus district — reception and Gallery cart'], {
      'meet-arca_quillon': say('Rejoindre Quillon près de la lampe éteinte.', 'Join Quillon beside the dark lamp.', 'Autrefois, j’aurais commencé par solder les comptes. La lampe d’abord.', 'Once, I would have started by closing the accounts. The lamp first.'),
      'intake-receipt': work('recover', 'raccord de la lampe de secours', 'emergency-lamp connector', 'Récupérer le raccord et suivre la marque Q-17.', 'Recover the connector and follow the Q-17 mark.', 'L’accueil a confié une seule clé Q-17 à la Galerie. Le raccord attend toujours cette clé.', 'Reception handed a single Q-17 key to the Gallery. The connector is still waiting for that key.'),
      'gallery-receipt': work('repair', 'lampe de secours et clé Q-17', 'emergency lamp and Q-17 key', 'Resserrer le raccord avec la clé retrouvée.', 'Tighten the connector with the recovered key.', 'La lampe s’allume. Q-17 est bien un seul outil ; le deuxième reçu copie la même remise.', 'The lamp lights up. Q-17 is one tool; the second slip copies the same handover.', 'Voilà ce qui manquait. Pas une seconde clé. Une main pour aller chercher la première.', 'That is what was missing. Not a second key. A hand willing to fetch the first.'),
      resolution: choose('Qui portera la différence ?', 'Who will carry the discrepancy?', {
        'link-copy': answer('Relier les deux reçus à l’unique clé retrouvée.', 'Link both slips to the single recovered key.', 'Quillon corrige le doublon sans réclamer un deuxième outil à un absent. La remise réelle reste identifiable.', 'Quillon corrects the duplicate without demanding a second tool from someone absent. The real handover remains identifiable.'),
        'hold-account': answer('Laisser le compte ouvert jusqu’au retour du témoin.', 'Leave the account open until the witness returns.', 'Quillon garde le compte provisoire. La clé est retrouvée et personne d’absent n’est chargé de combler l’écart.', 'Quillon keeps the account provisional. The key is found, and no absent person is made to cover the discrepancy.'),
        'charge-absent': answer('Faire payer le second outil au nom manquant.', 'Charge the missing name for the second tool.', '« Une personne ne devient pas coupable parce qu’elle n’est plus là pour protester. »', '“A person does not become guilty because they are no longer here to object.”')
      }),
      report: say('Revenir à l’ancre par le point d’accueil.', 'Return to the anchor through reception.', 'La lumière est revenue. Maintenant, je peux prendre le temps de répondre de mes comptes.', 'The light is back. Now I can take the time to answer for my accounts.')
    }),

  'city-nadir-return-probe-v1': quest('arca_nadir',
    ['La porte qui ne rend rien', 'The door that gives nothing back'],
    ['Un seuil du Nexus montre un Atrium intact, sans blessés ni décombres. Nadir ne retrouve aucune tension sur les fils tendus vers cette image. Il veut éprouver le passage depuis les deux côtés accessibles avant qu’une équipe ne s’y engage.', 'A Nexus threshold shows an untouched Atrium, without wounds or rubble. Nadir can feel no tension in the lines reaching toward that image. He wants to test the passage from its two accessible sides before a team commits to it.'],
    ['Ce refuge a exactement la couleur du mien. C’est ce qui m’inquiète. Attache la sonde ; si elle revient, je veux retrouver ses éraflures, pas une sonde neuve.', 'That shelter has exactly the color of mine. That worries me. Tie on the probe. If it comes back, I want its scratches back, not a new probe.'],
    ['Quartier Nexus — seuil de reconnaissance de Nadir', 'Nexus district — Nadir’s reconnaissance threshold'], {
      'meet-arca_nadir': say('Prendre le harnais auprès de Nadir.', 'Collect the harness from Nadir.', 'Tu n’as pas à prouver ton courage à une porte. Tu as à garder ton retour.', 'You do not owe a door proof of courage. You owe yourself a way back.'),
      'probe-origin': work('beacon', 'sonde et attache de harnais', 'probe and harness anchor', 'Attacher la sonde au point de départ.', 'Attach the probe at the starting point.', 'L’attache garde le nom de Nadir, l’heure et la marque usée de la sonde.', 'The anchor holds Nadir’s name, the time, and the probe’s worn mark.'),
      'probe-far-side': work('scan', 'borne de l’autre bord', 'far-edge post', 'Tendre le fil depuis la borne distante.', 'Tension the line from the far post.', 'La borne répond sur le trajet parcouru. L’image du refuge, plus loin, ne rend toujours aucune tension.', 'The post responds along the route walked. The shelter image beyond it still gives back no tension.'),
      'probe-return': work('recover', 'sonde de retour', 'return probe', 'Reprendre la même sonde à son point d’attache.', 'Recover the same probe at its anchor point.', 'La sonde revient avec la même usure et un temps écoulé cohérent. Ce trajet est réel ; les seuils voisins restent inconnus.', 'The probe returns with the same wear and a consistent elapsed time. This route is real; the neighboring thresholds remain unknown.'),
      resolution: choose('Jusqu’où guider la prochaine équipe ?', 'How far will you guide the next team?', {
        'bounded-return': answer('Baliser seulement le trajet dont la sonde est revenue.', 'Mark only the route from which the probe returned.', 'Nadir garde un aller-retour précis. L’image séduisante ne devient pas une issue sûre par voisinage.', 'Nadir keeps one specific round trip. The tempting image does not become a safe exit merely by being nearby.'),
        'repeat-probe': answer('Garder le départ fermé et refaire une sonde.', 'Keep departure closed and run another probe.', 'L’équipe attend. Nadir conserve le premier trajet observé sans prétendre qu’un second essai a déjà eu lieu.', 'The team waits. Nadir keeps the first observed route without pretending a second trial has already happened.'),
        'guarantee-all-routes': answer('Ouvrir tous les seuils sur la foi de ce retour.', 'Open every threshold on the strength of this return.', '« J’en ai ramené une sonde. Pas la promesse de toutes les portes. »', '“I brought back one probe. Not a promise from every door.”')
      }),
      report: say('Rejoindre l’ancre en suivant le fil réel.', 'Reach the anchor by following the real line.', 'Un peu de poussière sur le harnais. C’est mieux qu’un retour trop parfait.', 'A little dust on the harness. Better than a return that is too perfect.')
    }),

  'city-elyra-consented-door-v1': quest('arca_elyra',
    ['La porte a entendu non', 'The door heard no'],
    ['Une commande de passage relance une ouverture après le retrait d’un accord. Elyra reconnaît la faute : la machine garde la conséquence et jette le choix qui devait pouvoir l’arrêter.', 'A passage control restarts an opening after agreement has been withdrawn. Elyra recognizes the failure: the machine keeps the consequence and throws away the choice that should be able to stop it.'],
    ['Il a dit oui, puis il a dit non. La porte n’a gardé que ce qui l’arrange. Aide-moi à lui rendre son arrêt.', 'He said yes, then he said no. The door kept only the answer it wanted. Help me give it back its stop.'],
    ['Quartier Nexus — commande de passage Null', 'Nexus district — Null passage control'], {
      'meet-arca_elyra': say('Rejoindre Elyra à la commande bloquée.', 'Join Elyra at the jammed control.', 'On peut changer d’avis avant de franchir. Une porte qui l’oublie ne doit pas décider pour nous.', 'We can change our minds before crossing. A door that forgets that must not decide for us.'),
      'explicit-acceptance': work('scan', 'contact d’ouverture', 'opening contact', 'Distinguer l’accord reçu de la relance automatique.', 'Distinguish the given agreement from the automatic restart.', 'Le contact ne porte qu’un accord pour le premier passage. Rien n’autorise la relance suivante.', 'The contact carries agreement for the first passage only. Nothing authorizes the next restart.'),
      'withdrawn-token': work('secure', 'arrêt Null', 'Null stop', 'Couper la relance et rétablir l’arrêt de la porte.', 'Cut the restart and restore the door’s stop.', 'Le retrait du premier accord et le refus d’un second volontaire arrêtent la commande. L’ancien jeton ne peut plus ouvrir la porte.', 'Withdrawal of the first agreement and a second volunteer’s refusal stop the control. The old token can no longer open the door.', 'Tu vois ce violet ? Il ne manque rien. C’est la trace d’un non qui a tenu.', 'See that violet? Nothing is missing. It is the mark of a no that held.'),
      resolution: choose('Que laisser à la commande ?', 'What will you leave with the control?', {
        'honour-both': answer('Garder l’accord passé et son retrait, sans les réutiliser.', 'Keep the past agreement and its withdrawal without reusing them.', 'Chaque décision garde son sens. Un nouveau passage demandera un nouveau oui.', 'Each decision keeps its meaning. A new passage will need a new yes.'),
        'close-terminal': answer('Garder la commande fermée jusqu’à sa réparation complète.', 'Keep the control closed until it is fully repaired.', 'La porte reste fermée. Les choix des volontaires restent intacts, même si cela retarde le départ.', 'The door stays closed. The volunteers’ choices remain intact, even if departure is delayed.'),
        'reuse-consent': answer('Réutiliser le premier oui pour gagner du temps.', 'Reuse the first yes to save time.', '« Ce temps gagné, qui le paie ? Celui qui vient de te dire non. »', '“Who pays for the time you save? The person who just told you no.”')
      }),
      report: say('Revenir à l’ancre après avoir rendu son arrêt à la porte.', 'Return to the anchor after giving the door back its stop.', 'Je n’interdis pas le départ. Je veux qu’il appartienne à celui qui part.', 'I am not forbidding departure. I want it to belong to the person leaving.')
    }),

  'city-oryn-separate-voices-v1': quest('arca_oryn',
    ['Les mains derrière les noms', 'The hands behind the names'],
    ['À l’établi des arrivants, des outils de la Route X portent tous le nom d’Oryn. Les voix liées à leurs gardes ont été fondues en un seul appel. Il reconnaît le travail de ses voisins et refuse de les laisser disparaître derrière lui.', 'At the arrivals’ workbench, tools from Route X all bear Oryn’s name. The voices bound to their guards have been merged into one call. He recognizes his neighbors’ work and refuses to let them disappear behind him.'],
    ['Cette encoche n’est pas de moi. Celle-là non plus. J’ai réparé leurs lames, je ne les ai pas toutes forgées. Aide-moi à leur rendre leurs mains.', 'That notch is not mine. Neither is that one. I repaired their blades; I did not forge them all. Help me give them back their hands.'],
    ['Quartier Nexus — établi des ateliers de Route X', 'Nexus district — Route X workshop bench'], {
      'meet-arca_oryn': say('Retrouver Oryn auprès des outils sans noms.', 'Meet Oryn beside the nameless tools.', 'Je peux porter un nom jusqu’à son propriétaire. Pas devenir son propriétaire.', 'I can carry a name until it reaches its owner. I cannot become its owner.'),
      'workshop-signatures': work('recover', 'gardes gravées de Route X', 'engraved Route X guards', 'Dégager les marques d’artisans sous le sceau.', 'Uncover the makers’ marks beneath the seal.', 'Deux mains différentes réapparaissent dans les gravures. Une troisième marque reste incomplète ; ce vide n’appartient pas à Oryn.', 'Two different hands reappear in the engravings. A third mark remains incomplete; that gap does not belong to Oryn.'),
      'withdrawal-notice': work('secure', 'relais de voix de l’établi', 'workbench voice relay', 'Retirer du relais la voix qui ne veut plus être diffusée.', 'Remove the voice that no longer wishes to be broadcast from the relay.', 'Une contribution quitte l’appel public à la demande de son témoin. Sa place n’est pas remplie par la voix d’Oryn.', 'One contribution leaves the public call at its witness’s request. Oryn’s voice does not fill the space.'),
      resolution: choose('Quelles voix faire entendre à l’accueil ?', 'Which voices should reception hear?', {
        'separate-voices': answer('Laisser chaque voix autorisée porter son propre nom.', 'Let each willing voice carry its own name.', 'Les voix autorisées restent distinctes. Le retrait est respecté et le nom encore incomplet reste ouvert.', 'The willing voices remain distinct. Withdrawal is respected and the incomplete name remains open.'),
        'hold-attribution': answer('Attendre que chacun puisse reprendre sa propre parole.', 'Wait until each person can take back their own words.', 'L’appel reste en attente d’une relecture volontaire. Oryn ne prend la parole d’aucun absent.', 'The call waits for voluntary review. Oryn takes no absent person’s words.'),
        'one-spokesperson': answer('Mettre le nom d’Oryn sur toutes les voix.', 'Put Oryn’s name on every voice.', '« Je ne suis pas la dernière personne de ma rue. Cessez de faire comme si. »', '“I am not the last person from my street. Stop acting as if I am.”')
      }),
      report: say('Rejoindre l’ancre avec les marques séparées.', 'Reach the anchor with the marks kept separate.', 'Je reconnais leur travail. Un jour, chacun pourra dire lequel est le sien.', 'I recognize their work. One day each will be able to say which is theirs.')
    }, ['src/game/ocCampaign.js#8807']),

  'city-anchor-trace-return-v1': quest('player_anchor',
    ['Le feu du retour', 'The return light'],
    ['Une coupure prive le relais extérieur de sa lumière de retour. Le réseau peut utiliser ta signature pour le retrouver, mais il ne doit pas fabriquer une Ancre de remplacement à l’autre bout.', 'A power cut has taken the outer relay’s return light. The network can use your signature to find it, but must not manufacture a replacement Anchor at the other end.'],
    ['Je veux que cette lumière me ramène. Pas qu’elle garde une copie de moi pendant que je me perds.', 'I want that light to bring me back. Not keep a copy of me while I get lost.'],
    ['Quartier Nexus — relais extérieur et ancre de l’Atrium', 'Nexus district — outer relay and Atrium anchor'], {
      'inspect-nexus_anchor_coil': work('scan', 'bobine de référence', 'reference coil', 'Reprendre la pulsation de référence sur la bobine d’essai.', 'Recover the reference pulse from the test coil.', 'La bobine reconnaît toujours ton origine. Le relais pourra être comparé à cette pulsation.', 'The coil still recognizes your origin. The relay can be compared with this pulse.'),
      'inherited-route': fork('byOriginChoice', {
        'retain-origin': work('repair', 'prise du relais ouest', 'west relay socket', 'Rebrancher la prise portant tes deux échos conservés.', 'Reconnect the socket carrying your two retained echoes.', 'Les deux échos gardent la même origine. Aucun n’a été changé en personne supplémentaire.', 'Both echoes keep the same origin. Neither has been changed into an additional person.'),
        'ask-review': work('secure', 'verrou de fusion', 'merge lock', 'Maintenir la fusion coupée et dégager la prise de lecture.', 'Keep merging disconnected and clear the reading socket.', 'La fusion est toujours arrêtée. La prise permet de comparer tes échos sans les envoyer ailleurs.', 'Merging is still stopped. The socket lets your echoes be compared without sending them elsewhere.')
      }),
      crosscheck: work('route', 'fil de retour du relais', 'relay return line', 'Boucler le signal d’essai jusqu’à son point de départ.', 'Loop the test signal back to its starting point.', 'La pulsation revient avec ta référence initiale. La lumière peut indiquer un trajet sans prétendre être toi.', 'The pulse returns with your initial reference. The light can mark a route without claiming to be you.'),
      resolution: choose('Que fera ce feu pour toi ?', 'What will this light do for you?', {
        apply: answer('Raccorder le retour à mon origine.', 'Connect the return to my origin.', 'Tu choisis un relais qui renvoie vers toi, sans remplacer ton identité. Le raccord reste à fixer sur place.', 'You choose a relay that points back to you without replacing your identity. Its connection still needs securing on site.'),
        hold: answer('Garder une balise de lecture, sans transfert.', 'Keep a reading beacon, without transfer.', 'Tu gardes un repère consultable. Le transfert de signature doit rester fermé.', 'You keep a readable reference point. Signature transfer must stay closed.'),
        shortcut: answer('Envoyer une copie de moi pour tenir la lumière.', 'Send a copy of me to hold the light.', 'Une copie plus stable ne reçoit pas le droit de décider qui rentrera.', 'A more stable copy does not receive the right to decide who comes home.')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('repair', 'raccord du feu de retour', 'return-light connection', 'Fixer le raccord du feu sur ta référence d’origine.', 'Fasten the light’s connection to your origin reference.', 'Le feu renvoie ta pulsation initiale. Les deux échos restent distincts et personne ne t’a remplacé.', 'The light returns your initial pulse. The two echoes remain separate, and no one has replaced you.'),
        hold: work('secure', 'verrou du transfert', 'transfer lock', 'Verrouiller le transfert en laissant la lumière lisible.', 'Lock transfer while leaving the light readable.', 'La balise reste visible et consultable. Aucune signature ne franchit le verrou.', 'The beacon remains visible and readable. No signature crosses the lock.')
      }),
      report: say('Revenir sous la lumière de l’ancre de l’Atrium.', 'Return beneath the Atrium anchor’s light.', 'C’est un chemin vers moi. Pas une autre personne à ma place.', 'It is a way back to me. Not another person in my place.')
    }),

  'city-mirelle-relay-followup-v1': quest('arca_mirelle',
    ['Une réponse dans les parasites', 'An answer through the static'],
    ['Le relais de secours reçoit de nouveau une réponse, mais sa sortie grésille sous la charge. Mirelle veut lui rendre une liaison utilisable sans sacrifier la boucle qui protège les deux voix.', 'The emergency relay receives an answer again, but its output crackles under load. Mirelle wants a usable connection without sacrificing the loop protecting both voices.'],
    ['J’ai entendu une réponse. Courte, mais une réponse. Avant de leur dire de compter sur nous, aide-moi à faire revenir un signal propre.', 'I heard an answer. A short one, but an answer. Before I tell them to count on us, help me get a clean signal back.'],
    ['Quartier Nexus — sortie du relais de secours', 'Nexus district — emergency relay output'], {
      'meet-arca_mirelle': say('Revenir auprès de Mirelle et de sa boucle de secours.', 'Return to Mirelle and her backup loop.', 'La sauvegarde reste avec moi. C’est le circuit qu’on met à l’épreuve, pas les gens.', 'The backup stays with me. We are testing the circuit, not the people.'),
      'inherited-route': fork('byOriginChoice', {
        'separate-traces': work('repair', 'séparateur des deux canaux', 'two-channel separator', 'Resserrer les prises des deux canaux rétablis.', 'Tighten the sockets of the two restored channels.', 'Les deux canaux restent séparés. Leur sortie doit encore être éprouvée sous charge.', 'The two channels remain separate. Their output still needs testing under load.'),
        'isolate-relay': work('recover', 'prise d’essai de la boucle isolée', 'isolated loop test socket', 'Dégager la prise d’essai sans déplacer les voix.', 'Free the test socket without moving the voices.', 'Le relais est toujours isolé. Les deux voix restent dans la boucle, hors du circuit d’essai.', 'The relay is still isolated. Both voices remain in the loop, outside the test circuit.')
      }),
      crosscheck: work('scan', 'témoin de réponse', 'reply indicator', 'Envoyer une impulsion et écouter sa réponse.', 'Send a pulse and listen for its reply.', 'La même impulsion revient par le circuit. Aucun canal n’a pris le nom de l’autre.', 'The same pulse returns through the circuit. Neither channel has taken the other’s name.', 'Ça revient. On sait au moins quelle porte on vient de frapper.', 'It comes back. At least we know which door we just knocked on.'),
      resolution: choose('Comment rester joignables ?', 'How will you stay reachable?', {
        apply: answer('Rouvrir un seul canal sous surveillance.', 'Reopen one monitored channel.', 'Mirelle prépare une liaison limitée et garde la boucle séparée. Il faut encore raccorder sa sortie.', 'Mirelle prepares a limited connection and keeps the loop separate. Its output still needs connecting.'),
        hold: answer('Isoler le circuit et garder la réponse d’essai.', 'Isolate the circuit and keep the test reply.', 'Mirelle accepte d’attendre. Le circuit doit être isolé, même s’il avait été rouvert auparavant.', 'Mirelle agrees to wait. The circuit must be isolated even if it was reopened before.'),
        shortcut: answer('Vider la sauvegarde maintenant que le test répond.', 'Empty the backup now that the test answers.', '« Ce bip ne vaut pas leurs vies. La boucle reste. »', '“That beep is not worth their lives. The loop stays.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('repair', 'sortie surveillée du relais', 'monitored relay output', 'Raccorder le canal et maintenir son témoin de retour.', 'Connect the channel and keep its return indicator on.', 'Le canal répond sous son propre identifiant. La boucle de sauvegarde reste indépendante.', 'The channel answers under its own identifier. The backup loop stays independent.'),
        hold: work('secure', 'coupe-circuit du relais', 'relay cutout', 'Couper le circuit et sceller sa prise de sortie.', 'Cut the circuit and seal its output socket.', 'Le circuit est isolé. La réponse d’essai et les deux voix sont conservées séparément.', 'The circuit is isolated. The test reply and both voices are kept separately.')
      }),
      report: say('Revenir à l’ancre en laissant la boucle à Mirelle.', 'Return to the anchor with the loop left in Mirelle’s care.', 'Je leur dirai exactement ce qu’on peut tenir. Elles ont déjà entendu assez de belles promesses.', 'I will tell them exactly what we can hold. They have heard enough beautiful promises.')
    }),

  'city-bastion-tenth-witness-v1': quest('arca_bastion',
    ['Les coups du Rempart', 'The knocking at the Bulwark'],
    ['Des coups résonnent dans un battant du Rempart Est. Ils rappellent à Bastion une fermeture qu’il n’a jamais oubliée. Un témoignage situe la même porte, mais ne dit pas qui se trouvait derrière ; il faut d’abord empêcher le battant de blesser un passant.', 'Knocking echoes through a panel of the East Bulwark. It reminds Bastion of a closure he has never forgotten. A witness account places the same door but does not name who was behind it; first, the swinging panel must be stopped from hurting a passerby.'],
    ['J’entends ces coups même quand la porte se tait. Aujourd’hui, elle bouge vraiment. Tiens le levier avec moi. Après, on écoutera ce que le témoin sait, pas ce que j’espère.', 'I hear that knocking even when the door is silent. Today it really is moving. Hold the lever with me. Afterward we will listen to what the witness knows, not what I hope.'],
    ['Quartier Nexus — battant de service du Rempart Est', 'Nexus district — East Bulwark service panel'], {
      'meet-arca_bastion': say('Rejoindre Bastion au levier du Rempart.', 'Join Bastion at the Bulwark lever.', 'Je ne vais pas tenir cette poignée toute ma vie. Aide-moi à la caler correctement.', 'I am not going to hold this handle for the rest of my life. Help me brace it properly.'),
      'inherited-route': fork('byOriginChoice', {
        'name-debt': work('recover', 'repère laissé par le témoin', 'witness’s marker', 'Reprendre le repère apporté après l’appel aux témoins.', 'Recover the marker brought after the call for witnesses.', 'Un témoin a laissé sa signature et la position d’une porte. Il n’a pas donné les noms de tous ceux qui se trouvaient derrière.', 'A witness left their signature and the position of a door. They did not give the names of everyone behind it.'),
        'attach-unknowns': work('scan', 'marque de fermeture du Rempart', 'Bulwark closure mark', 'Retrouver sur le battant la marque de la fermeture conservée.', 'Find the retained closure mark on the panel.', 'La marque correspond à une porte condamnée. Elle ne rend pas les noms qui manquent encore.', 'The mark matches a condemned door. It does not restore the names still missing.')
      }),
      crosscheck: work('repair', 'cale du battant', 'panel brace', 'Caler le battant et comparer sa fermeture à l’appel du témoin.', 'Brace the panel and compare its closure with the witness’s account.', 'Le battant cesse de cogner. L’heure et la position concordent avec le témoin : il a reconnu cette porte, sans pouvoir nommer ceux qui se trouvaient derrière.', 'The panel stops knocking. The time and position agree with the witness: they recognized this door without being able to name the people behind it.', 'C’était le battant. Je voulais entendre autre chose. Merci de ne pas me l’avoir inventé.', 'It was the panel. I wanted to hear something else. Thank you for not inventing it for me.'),
      resolution: choose('Que porter près de cette porte ?', 'What will you place beside this door?', {
        apply: answer('Garder le témoignage avec les noms encore manquants.', 'Keep the account alongside the names still missing.', 'Bastion accepte ce que le témoin apporte sans lui faire nommer des personnes qu’il n’a pas reconnues.', 'Bastion accepts what the witness offers without making them name people they did not recognize.'),
        hold: answer('Attendre un autre témoin avant d’attribuer davantage.', 'Wait for another witness before attributing anything more.', 'La fermeture reste reconnue. Ce nouveau récit attendra une autre voix, sans combler le silence à sa place.', 'The closure stays acknowledged. This new account will wait for another voice without filling the silence for it.'),
        shortcut: answer('Inscrire des noms pour en finir avec cette porte.', 'Write in names to be done with this door.', '« Je ne leur bâtirai pas une tombe avec des noms choisis pour me soulager. »', '“I will not build them a grave with names chosen to make me feel better.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('beacon', 'veilleuse du témoin', 'witness lamp', 'Rallumer la veilleuse auprès du témoignage conservé.', 'Relight the lamp beside the retained testimony.', 'La veilleuse éclaire le témoignage, la marque de cette porte et les places laissées aux noms encore inconnus.', 'The lamp lights the testimony, this door’s mark, and the spaces left for names still unknown.'),
        hold: work('secure', 'abri du témoignage en attente', 'shelter for the pending account', 'Mettre le témoignage à l’abri près du poste de garde.', 'Shelter the account beside the guard post.', 'Le récit reste accessible, avec la raison de l’attente. Le battant réparé ne menace plus le passage.', 'The account remains accessible with the reason for the wait. The repaired panel no longer threatens the passage.')
      }),
      report: say('Retourner à l’ancre par le poste de garde.', 'Return to the anchor through the guard post.', 'Je peux quitter cette poignée. Pas leur souvenir.', 'I can leave this handle. Not their memory.')
    }),

  'city-nova-return-measurement-v1': quest('arca_nova',
    ['Le battement qui revient', 'The beat that returns'],
    ['Les deux bords du passage commencent enfin à se répondre. Leur décalage varie encore. Nova veut une lumière qui montre quand attendre, plutôt qu’une flèche qui promet de passer à n’importe quel instant.', 'The passage’s two edges are finally beginning to answer each other. Their delay still varies. Nova wants a light that shows when to wait rather than an arrow promising passage at any moment.'],
    ['Il y a un retour cette fois. Je l’entends dans le diapason. Aide-moi à le suivre jusqu’au bout avant que je me mette à y croire trop fort.', 'There is a return this time. I can hear it in the tuner. Help me follow it all the way before I start believing in it too much.'],
    ['Quartier Nexus — deux bords du passage pulsé', 'Nexus district — both edges of the pulsing passage'], {
      'meet-arca_nova': say('Rejoindre Nova auprès de sa sonde.', 'Join Nova beside her probe.', 'On ne jette pas la première mesure parce que la nouvelle nous plaît davantage.', 'We do not throw out the first measurement because we like the new one better.'),
      'inherited-route': fork('byOriginChoice', {
        'mark-uncertainty': work('scan', 'sonde au retour inconnu', 'probe with unknown return', 'Reprendre la sonde qui signalait le retour manquant.', 'Retrieve the reading from the probe that marked the missing return.', 'La première mesure garde son avertissement. Elle attend encore un retour observé séparément.', 'The first measurement keeps its warning. It still awaits a separately observed return.'),
        'require-return': work('beacon', 'repère du départ suspendu', 'held-departure marker', 'Fixer la nouvelle sonde sur le départ resté fermé.', 'Set the new probe at the departure point that stayed closed.', 'Le départ n’avait pas été autorisé. Sa référence intacte peut maintenant servir à cette observation.', 'Departure had not been authorized. Its intact reference can now be used for this observation.')
      }),
      crosscheck: work('scan', 'diapason de retour', 'return tuner', 'Suivre la contre-pulsation jusqu’à la sonde de départ.', 'Follow the counter-pulse back to the departure probe.', 'La même signature revient. Son délai varie entre les pulsations : il faut laisser une marge d’attente.', 'The same signature returns. Its delay varies between pulses: a waiting margin is needed.', 'Pas une seconde de moins parce qu’on est pressés. Le sol n’en sait rien.', 'Not one second less because we are in a hurry. The ground does not know that.'),
      resolution: choose('Comment guider un départ prudent ?', 'How will you guide a cautious departure?', {
        apply: answer('Montrer le trajet avec sa marge d’attente.', 'Show the route with its waiting margin.', 'Nova prépare un repère limité à ce trajet et à l’heure observée. La lumière doit encore être réglée.', 'Nova prepares a marker limited to this route and the time observed. The light still needs setting.'),
        hold: answer('Attendre une mesure à une autre heure.', 'Wait for a measurement at another time.', 'Nova garde ce premier retour sans le remplacer. La comparaison reste à faire.', 'Nova keeps this first return without replacing it. The comparison is still to be made.'),
        shortcut: answer('Garantir toutes les sorties avec ce seul retour.', 'Guarantee every exit from this one return.', '« Une bonne nouvelle n’est pas une prophétie. »', '“Good news is not a prophecy.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('beacon', 'feu de contre-pulsation', 'counter-pulse light', 'Régler le feu sur le délai et l’heure observés.', 'Set the light to the observed delay and time.', 'Le feu indique la route et sa marge d’attente. Il ne promet rien au-delà des mesures conservées.', 'The light shows the route and its waiting margin. It promises nothing beyond the retained measurements.'),
        hold: work('secure', 'sonde de comparaison', 'comparison probe', 'Préparer la sonde pour la prochaine observation sans effacer la première.', 'Prepare the probe for the next observation without erasing the first.', 'La référence reste prête. La seconde mesure n’a pas encore eu lieu et le premier retour est conservé.', 'The reference stays ready. The second measurement has not happened yet, and the first return is retained.')
      }),
      report: say('Revenir à l’ancre entre les deux pulsations.', 'Return to the anchor between the pulses.', 'Ce que je peux te donner, c’est une chance de choisir en sachant. Pas un monde sans pertes.', 'What I can give you is a chance to choose with your eyes open. Not a world without loss.')
    }),

  'city-sable-map-detour-v1': quest('arca_sable',
    ['Le détour dans la poussière', 'The detour in the dust'],
    ['Une nouvelle barrière a coupé le circuit balisé par Sable. Les anciennes flèches sont encore lisibles, et donc encore dangereuses. Le détour doit retrouver le quartier sans conduire quelqu’un dans la même impasse.', 'A new barrier has cut through Sable’s marked circuit. The old arrows are still readable, which makes them dangerous. The detour must rejoin the district without leading anyone into the same dead end.'],
    ['Ma signature est encore sur cette carte. C’est donc moi qui viens déplacer les flèches. Marche avec moi ; la poussière cache le débouché.', 'My signature is still on that map. So I am the one coming to move the arrows. Walk with me. Dust is hiding where the detour comes out.'],
    ['Quartier Nexus — ancien accès et débouché du détour', 'Nexus district — old access and detour exit'], {
      'meet-arca_sable': say('Rejoindre Sable devant la barrière nouvelle.', 'Join Sable at the new barrier.', 'Une carte peut avoir été juste hier. Ça ne la rend pas sûre aujourd’hui.', 'A map may have been right yesterday. That does not make it safe today.'),
      'inherited-route': fork('byOriginChoice', {
        'signed-correction': work('secure', 'flèche de la correction signée', 'signed-correction arrow', 'Décrocher la flèche qui pointe désormais vers la barrière.', 'Unhook the arrow now pointing at the barrier.', 'La correction était exacte au moment du relevé. La nouvelle barrière est signalée sans falsifier cet ancien trajet.', 'The correction was accurate when surveyed. The new barrier is marked without falsifying that earlier route.'),
        'annotated-original': work('scan', 'repères des deux anciennes cartes', 'markers from the two earlier maps', 'Comparer les anciens repères à la barrière apparue.', 'Compare the old markers with the new barrier.', 'Les deux cartes montrent le changement. Aucune ne donne encore un retour vérifié par le nouveau détour.', 'Both maps show the change. Neither yet gives a verified return along the new detour.')
      }),
      crosscheck: work('route', 'repère du débouché', 'exit marker', 'Parcourir le détour jusqu’à son débouché dans le quartier.', 'Walk the detour to where it rejoins the district.', 'Le détour rejoint le quartier sans franchir la barrière. Sa largeur a été vérifiée sur place.', 'The detour rejoins the district without crossing the barrier. Its width has been checked on site.', 'On retrouve la rue ici. Pas là où la vieille flèche nous le jurait.', 'The street comes back here. Not where the old arrow swore it would.'),
      resolution: choose('Que montrer à ceux qui arrivent ?', 'What will you show people arriving?', {
        apply: answer('Baliser ce détour avec l’heure et nos noms.', 'Mark this detour with the time and our names.', 'Sable assume le nouveau trajet mesuré. Les flèches doivent maintenant conduire à son vrai débouché.', 'Sable takes responsibility for the newly measured route. The arrows must now lead to its real exit.'),
        hold: answer('Fermer l’ancien accès et attendre un second passage.', 'Close the old access and wait for a second survey.', 'L’ancien accès doit rester fermé. Le détour attend une autre mesure avant d’être proposé à tous.', 'The old access must stay closed. The detour awaits another measurement before being offered to everyone.'),
        shortcut: answer('Laisser les flèches en place pour ne pas refaire la carte.', 'Leave the arrows where they are to avoid remaking the map.', '« Si on sait qu’elle ment, ce n’est plus une erreur de carte. C’est notre choix. »', '“If we know it lies, it is no longer a map error. It is our choice.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('beacon', 'flèche du détour', 'detour arrow', 'Fixer la nouvelle flèche vers le débouché parcouru.', 'Fasten the new arrow toward the exit you walked.', 'La flèche suit le détour mesuré et porte vos noms et l’heure du passage.', 'The arrow follows the measured detour and carries your names and the time you walked it.'),
        hold: work('secure', 'barre de l’ancien accès', 'old-access bar', 'Barrer l’ancien accès et laisser le détour en attente.', 'Bar the old access and keep the detour on hold.', 'L’accès coupé est clairement fermé. Aucune flèche ne promet encore un détour ouvert à tous.', 'The cut access is clearly closed. No arrow yet promises a detour open to everyone.')
      }),
      report: say('Rejoindre l’ancre par le terrain que tu viens de parcourir.', 'Reach the anchor over the ground you just walked.', 'La prochaine fois qu’elle bouge, on reviendra. Une signature, ça sert aussi à ça.', 'When it moves again, we will come back. That is another thing a signature is for.')
    }),

  'city-loom-receiving-end-v1': quest('arca_loom',
    ['Personne à l’autre bout', 'No one at the other end'],
    ['Le fil de Loom peut revenir, mais le refuge n’a jamais accueilli une voix. Sa borne répond comme une machine. Loom veut un raccord utile pour les relevés du secours, sans faire d’une conscience le prochain essai.', 'Loom’s thread can return, but the shelter has never received a voice. Its terminal answers like a machine. Loom wants a connection useful for rescue readings without making a consciousness the next test.'],
    ['J’ai posé un lit devant cette borne. Elle sait compter sa température. Elle ne sait toujours pas répondre à quelqu’un qui a peur. Les voix restent avec moi.', 'I put a bed beside that terminal. It can count its temperature. It still cannot answer someone who is afraid. The voices stay with me.'],
    ['Quartier Nexus — départ du fil et borne d’accueil', 'Nexus district — thread departure and reception terminal'], {
      'meet-arca_loom': say('Retrouver Loom au point de récupération.', 'Meet Loom at the recovery point.', 'Un signal reçu n’est pas une personne accueillie. On va garder cette différence.', 'A received signal is not a person welcomed. We are going to keep that distinction.'),
      'inherited-route': fork('byOriginChoice', {
        'verify-thread': work('repair', 'attache du retour vérifié', 'verified-return anchor', 'Retendre la ligne dont le retour a été parcouru.', 'Retension the line whose return was walked.', 'La ligne garde sa tension. Aucun accueil d’une voix n’a été observé au refuge.', 'The line keeps its tension. No reception of a voice has been observed at the shelter.'),
        'retain-local': work('secure', 'noyau de secours du drone', 'drone backup core', 'Protéger le noyau pendant le raccord des instruments.', 'Protect the core while connecting the instruments.', 'Les voix sont toujours ici. Les anciens relevés transmis ne contenaient aucune copie de leur mémoire.', 'The voices are still here. The readings sent earlier contained no copy of their memory.')
      }),
      crosscheck: work('scan', 'borne d’accueil muette', 'silent reception terminal', 'Faire répondre la borne à une mesure de température.', 'Make the terminal answer a temperature reading.', 'La borne reçoit la mesure technique. Elle n’apporte aucune preuve qu’une conscience y serait accueillie.', 'The terminal receives the technical reading. It provides no evidence that a consciousness would be welcomed there.', 'Elle a entendu le nombre. Pas la personne. Pas encore.', 'It heard the number. Not the person. Not yet.'),
      resolution: choose('Que laisser passer dans le fil ?', 'What will you let travel down the thread?', {
        apply: answer('Seulement les mesures des instruments de secours.', 'Only readings from rescue instruments.', 'Loom autorise une liaison technique. Un filtre doit garder les voix hors du circuit.', 'Loom allows a technical connection. A filter must keep the voices out of the circuit.'),
        hold: answer('Fermer le fil jusqu’à ce que le refuge soit prêt.', 'Close the thread until the shelter is ready.', 'Loom suspend l’usage de la ligne sans perdre la route déjà parcourue.', 'Loom suspends use of the line without losing the route already walked.'),
        shortcut: answer('Envoyer une voix pour savoir si elle revient.', 'Send a voice to find out whether it returns.', '« Non. Pas l’une d’elles à la place d’une sonde. »', '“No. Not one of them in place of a probe.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('repair', 'filtre des instruments', 'instrument filter', 'Raccorder les instruments derrière le filtre de voix.', 'Connect the instruments behind the voice filter.', 'Le filtre laisse passer les mesures et bloque les voix. Le noyau du drone reste leur abri.', 'The filter passes readings and blocks voices. The drone core remains their shelter.'),
        hold: work('secure', 'fermeture du départ', 'departure closure', 'Fermer le départ en gardant le fil et ses repères.', 'Close departure while retaining the thread and its markers.', 'Le départ est fermé. Le trajet de retour et les voix conservées n’ont pas été effacés.', 'Departure is closed. The return route and the retained voices have not been erased.')
      }),
      report: say('Revenir à l’ancre avec le drone toujours auprès de Loom.', 'Return to the anchor with the drone still beside Loom.', 'Je peux attendre qu’on sache les accueillir. Je ne peux pas leur demander de disparaître pour nous apprendre comment.', 'I can wait until we know how to welcome them. I cannot ask them to disappear to teach us how.')
    }),

  'city-marrow-independent-answers-v1': quest('arca_marrow',
    ['Deux places à l’accueil', 'Two places at reception'],
    ['Les empreintes dégagées du sceau n’ont pas besoin de la même chose. Une borne d’accueil insiste pourtant pour les faire répondre sur un seul canal. Marrow veut leur laisser une place sans transformer la rencontre en duel.', 'The imprints freed from the seal do not need the same thing. A reception terminal still insists on making them answer through one channel. Marrow wants to give them room without turning the meeting into a duel.'],
    ['L’une veut retrouver ses souvenirs. L’autre veut qu’on lui laisse de l’espace. Ce n’est pas une contradiction à trancher. Aide-moi à leur faire deux places.', 'One wants to find their memories. The other wants room to breathe. That is not a contradiction to cut through. Help me make two places for them.'],
    ['Quartier Nexus — bornes d’accueil des deux empreintes', 'Nexus district — reception posts for the two imprints'], {
      'meet-arca_marrow': say('Rejoindre Marrow entre les deux bornes.', 'Join Marrow between the two posts.', 'Elles n’ont pas à se ressembler moins pour que je les laisse tranquilles.', 'They do not have to look less alike for me to leave them alone.'),
      'inherited-route': fork('byOriginChoice', {
        'separate-testimony': work('recover', 'deux appels séparés', 'two separate calls', 'Reprendre chaque appel sur son propre canal.', 'Retrieve each call on its own channel.', 'La première empreinte demande accès à ses souvenirs conservés ; la seconde demande un espace distinct.', 'The first imprint asks to access their retained memories; the second asks for a separate space.'),
        'request-dialogue': work('secure', 'commande de rencontre', 'meeting control', 'Arrêter l’appel forcé et écouter les deux réponses.', 'Stop the forced call and listen to both replies.', 'Une empreinte accepte l’échange. L’autre demande du temps. Son silence ne réclame la place de personne.', 'One imprint accepts the conversation. The other asks for time. Their silence claims no one else’s place.')
      }),
      crosscheck: work('repair', 'séparateur de la borne d’accueil', 'reception-post separator', 'Séparer les prises de réponse de la borne.', 'Separate the post’s reply sockets.', 'Deux réponses restent liées à deux signatures. Aucune ne demande que l’autre disparaisse.', 'Two replies remain tied to two signatures. Neither asks for the other to disappear.', 'Voilà ce qu’elles choisissent. Le reste n’est pas à ma lame de l’inventer.', 'That is what they choose. The rest is not for my blade to invent.'),
      resolution: choose('Comment préparer leur prochain échange ?', 'How will you prepare their next conversation?', {
        apply: answer('Garder deux espaces, chacun avec sa propre demande.', 'Keep two spaces, each with its own request.', 'Marrow prépare deux accueils distincts. Leurs demandes doivent rester séparées jusque sur les bornes.', 'Marrow prepares two separate reception points. Their requests must stay separate all the way to the posts.'),
        hold: answer('Suspendre la rencontre sans supprimer leurs demandes.', 'Suspend the meeting without deleting their requests.', 'Marrow laisse l’échange en attente. Une nouvelle rencontre reste à organiser, sans accusation ajoutée au silence.', 'Marrow leaves the meeting on hold. Another meeting still needs arranging, without turning silence into an accusation.'),
        shortcut: answer('Les faire combattre pour désigner l’original.', 'Make them fight to decide who is the original.', '« Le survivant d’un duel n’est pas la preuve que l’autre n’avait pas droit de vivre. »', '“The survivor of a duel is not proof that the other had no right to live.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('beacon', 'deux places d’accueil', 'two reception places', 'Régler chaque borne sur la demande qui lui appartient.', 'Set each post to the request that belongs to it.', 'Chaque borne garde sa signature et sa demande. Aucun canal n’est obligé d’imiter l’autre.', 'Each post keeps its own signature and request. Neither channel is forced to imitate the other.'),
        hold: work('secure', 'verrou de rencontre', 'meeting lock', 'Verrouiller l’appel commun en gardant les deux réponses.', 'Lock the shared call while keeping both replies.', 'La rencontre est suspendue. Les deux demandes restent disponibles pour un échange à organiser plus tard.', 'The meeting is suspended. Both requests remain available for a conversation to be arranged later.')
      }),
      report: say('Revenir à l’ancre en laissant les deux empreintes décider de la suite.', 'Return to the anchor and leave both imprints to decide what comes next.', 'Pour une fois, je peux ranger ma lame sans avoir abandonné quelqu’un.', 'For once, I can put my blade away without having abandoned someone.')
    }),

  'city-tessera-caption-review-v1': quest('arca_tessera',
    ['Son nom sur la porte', 'Her name on the door'],
    ['Le petit projecteur d’accueil ne sait résumer la chambre de Tessera qu’en supprimant une de ses origines. Cette fois, elle veut choisir elle-même ce que la porte dira aux arrivants.', 'The small reception projector can only summarize Tessera’s room by dropping one of her origins. This time she wants to choose what the door tells arriving people herself.'],
    ['Je n’ai pas besoin que toute la rue connaisse ma vie. Mais si la porte dit quelque chose, qu’elle dise mon nom sans en jeter la moitié derrière moi.', 'I do not need the whole street to know my life. But if the door says anything, let it say my name without throwing half of me away.'],
    ['Quartier Nexus — projecteur d’accueil de la Galerie', 'Nexus district — Gallery reception projector'], {
      'meet-arca_tessera': say('Rejoindre Tessera devant la porte projetée.', 'Join Tessera in front of the projected door.', 'Tu peux m’aider à régler les lettres. Ce qu’elles disent de moi, je veux pouvoir le relire.', 'You can help me set the letters. What they say about me, I want to be able to read again.'),
      'inherited-route': fork('byOriginChoice', {
        'parallel-accounts': work('scan', 'deux fragments conservés', 'two retained fragments', 'Reprendre les deux souvenirs sans les superposer.', 'Retrieve both memories without overlapping them.', 'Les deux souvenirs portent le nom de Tessera. Aucun ne fait d’elle le remplacement de l’agente disparue.', 'Both memories carry Tessera’s name. Neither makes her the lost agent’s replacement.'),
        'hold-display': work('secure', 'projecteur resté éteint', 'projector left dark', 'Garder la projection coupée pendant la relecture de Tessera.', 'Keep the projection off while Tessera reviews it.', 'La projection est restée en attente. Personne n’a publié une nouvelle présentation au nom de Tessera.', 'The projection has stayed on hold. No one has published a new account in Tessera’s name.')
      }),
      crosscheck: work('repair', 'ligne courte du projecteur', 'projector’s short line', 'Rendre au projecteur le souvenir qu’il avait coupé.', 'Restore the memory the projector cut from its short line.', 'La ligne garde enfin les deux origines et le nom choisi. Tessera peut les relire sans qu’un souvenir remplace l’autre.', 'The line finally keeps both origins and the chosen name. Tessera can review them without one memory replacing the other.', 'Tessera Vale. Une enfance dont je me souviens, une Forge dont je suis sortie. Écris-le comme ça.', 'Tessera Vale. A childhood I remember, a Foundry I walked out of. Write it like that.'),
      resolution: choose('Que montrer à l’accueil ?', 'What will reception show?', {
        apply: answer('Afficher le nom choisi et les deux souvenirs attribués.', 'Display the chosen name and both attributed memories.', 'La porte peut porter la présentation relue par Tessera. Il reste à régler son affichage public.', 'The door can carry the account Tessera reviewed. Its public display still needs setting.'),
        hold: answer('Laisser la version courte en attente de sa relecture finale.', 'Leave the short version awaiting her final review.', 'Le petit projecteur attendra. Les deux souvenirs restent accessibles sans nouvelle présentation imposée.', 'The small projector will wait. Both memories remain accessible without another account imposed on her.'),
        shortcut: answer('Choisir l’origine la plus facile à raconter.', 'Choose the origin that is easiest to explain.', '« Une histoire plus courte n’est pas une raison de me faire plus petite. »', '“A shorter story is no reason to make me smaller.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('beacon', 'nom de Tessera à l’accueil', 'Tessera’s name at reception', 'Allumer la présentation portant ses deux origines.', 'Light the account carrying both of her origins.', 'Le projecteur affiche Tessera Vale et les deux souvenirs avec leurs provenances distinctes.', 'The projector displays Tessera Vale and both memories with their distinct origins.'),
        hold: work('secure', 'volet du petit projecteur', 'small projector shutter', 'Fermer le volet public en gardant les deux fragments consultables.', 'Close the public shutter while keeping both fragments accessible.', 'L’accueil signale que Tessera relit sa présentation. Les deux souvenirs n’ont pas été supprimés.', 'Reception shows that Tessera is reviewing her account. Neither memory has been deleted.')
      }),
      report: say('Revenir à l’ancre en laissant la porte à Tessera.', 'Return to the anchor and leave the door with Tessera.', 'C’est étrange de choisir une si petite chose. Étrange et bien.', 'It is strange to choose such a small thing. Strange, and good.')
    }),

  'city-quillon-delivery-check-v1': quest('arca_quillon',
    ['Le courant doit arriver ici', 'The power must reach here'],
    ['Le raccord de la lampe tient, mais une alimentation mal aiguillée fait encore trembler la lumière de l’accueil. Quillon veut suivre le courant avec l’unique clé Q-17 déjà livrée à la Galerie, sans créer une seconde dette sur le papier.', 'The lamp connection holds, but a misrouted supply still makes reception’s light flicker. Quillon wants to follow the current with the single Q-17 key already delivered to the Gallery, without creating a second debt on paper.'],
    ['On a rendu la lumière. Pas encore le courant qu’elle peut garder. Q-17 est à la Galerie, je le sais. Retrouvons le mauvais raccord avant de réclamer un outil qui n’a jamais existé.', 'We brought back the light. Not yet the power it can keep. Q-17 is at the Gallery; I know that. Let us find the wrong connection before asking for a tool that never existed.'],
    ['Quartier Nexus — alimentation de l’accueil et établi de la Galerie', 'Nexus district — reception supply and Gallery bench'], {
      'meet-arca_quillon': say('Rejoindre Quillon près de l’alimentation.', 'Join Quillon beside the supply.', 'Le témoin peut encore manquer au comptoir. Ça ne fait pas disparaître la clé de l’établi.', 'The witness may still be missing from the counter. That does not make the key vanish from the bench.'),
      'inherited-route': fork('byOriginChoice', {
        'link-copy': work('scan', 'marque de l’unique livraison', 'single-delivery mark', 'Suivre le raccord portant la marque de la remise unique.', 'Follow the connection marked with the single handover.', 'La même remise conduit à Q-17. Son destinataire n’a pas encore confirmé localement la réception.', 'The same handover leads to Q-17. Its recipient has not yet confirmed receipt locally.'),
        'hold-account': work('recover', 'prise de Q-17 à la Galerie', 'Q-17 socket at the Gallery', 'Retrouver Q-17 à son établi malgré le compte resté ouvert.', 'Find Q-17 at its bench despite the account remaining open.', 'Q-17 avait déjà été livré à la Galerie. Seul le compte est provisoire ; il n’y a ni nouvel outil ni seconde remise.', 'Q-17 had already been delivered to the Gallery. Only the account is provisional; there is no new tool or second handover.')
      }),
      crosscheck: work('repair', 'raccord d’alimentation de l’accueil', 'reception supply connection', 'Rétablir l’alimentation avec la clé Q-17 retrouvée.', 'Restore the supply using the recovered Q-17 key.', 'La lampe reçoit son alimentation. La marque du raccord et l’accusé renvoient au même outil déjà livré, pas à une autre clé.', 'The lamp receives its supply. The connection mark and acknowledgment point to the same tool already delivered, not another key.', 'Une seule clé. Un seul trajet. Et cette fois, la lumière tient.', 'One key. One journey. And this time the light holds.'),
      resolution: choose('Comment laisser cette remise à ceux qui reprendront l’atelier ?', 'How will you leave this handover for those taking over the workshop?', {
        apply: answer('Confirmer cette remise unique et son destinataire.', 'Confirm this single handover and its recipient.', 'Quillon rapproche l’accusé de la remise existante. La clé ne devient pas une deuxième ressource.', 'Quillon links the acknowledgment to the existing handover. The key does not become a second resource.'),
        hold: answer('Attendre le témoin en gardant le compte provisoire.', 'Wait for the witness and keep the account provisional.', 'Le compte reste ouvert jusqu’à la confirmation en personne. Personne ne reçoit une dette nouvelle pour cette attente.', 'The account stays open until confirmation in person. No one receives a new debt because of the wait.'),
        shortcut: answer('Utiliser la copie pour réclamer une seconde livraison.', 'Use the copy to demand a second delivery.', '« Une photocopie ne serre aucun boulon. Elle ne crée pas un outil non plus. »', '“A photocopy tightens no bolts. It does not create a tool either.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('beacon', 'repère de remise de Q-17', 'Q-17 handover marker', 'Relier le témoin de remise à la marque unique de Q-17.', 'Link the handover indicator to Q-17’s single mark.', 'Le comptoir montre une seule remise et son accusé. Q-17 garde la même provenance.', 'The counter shows one handover and its acknowledgment. Q-17 keeps the same origin.'),
        hold: work('secure', 'emplacement de Q-17 à la Galerie', 'Q-17’s place at the Gallery', 'Garder la clé à la Galerie et sa confirmation en attente.', 'Keep the key at the Gallery and its confirmation pending.', 'L’outil reste à la Galerie. Le compte garde la confirmation manquante sans inventer de remise ou de dette.', 'The tool remains at the Gallery. The account retains the missing confirmation without inventing a handover or debt.')
      }),
      report: say('Revenir à l’ancre par l’accueil éclairé.', 'Return to the anchor through the lit reception point.', 'Ils peuvent attendre à la lumière. Le reste, je le prendrai sur mon temps. Pas sur leur dos.', 'They can wait in the light. The rest can take my time. It will not come out of their lives.')
    }),

  'city-nadir-second-threshold-v1': quest('arca_nadir',
    ['La seconde porte', 'The second door'],
    ['Au-delà du trajet sondé, un second seuil imite la même lumière de retour. Nadir veut empêcher qu’un repère honnête serve de caution à une porte qui n’a encore rien rendu.', 'Beyond the probed route, a second threshold imitates the same return light. Nadir wants to stop an honest marker from vouching for a door that has not yet given anything back.'],
    ['Tu vois la deuxième lumière ? Elle copie la première, jusque dans son défaut. Je ne lui confierai personne tant qu’elle n’aura pas rendu autre chose qu’une belle image.', 'See the second light? It copies the first, right down to its flaw. I will trust it with no one until it gives back more than a beautiful image.'],
    ['Quartier Nexus — limite entre les deux seuils', 'Nexus district — boundary between the two thresholds'], {
      'meet-arca_nadir': say('Rejoindre Nadir avant le second seuil.', 'Join Nadir before the second threshold.', 'On s’arrête à la tension du fil. Pas à la couleur de la lumière.', 'We stop where the line holds tension. Not where the light changes color.'),
      'inherited-route': fork('byOriginChoice', {
        'bounded-return': work('beacon', 'fin du premier trajet', 'end of the first route', 'Retrouver la dernière attache du trajet vérifié.', 'Find the last anchor of the verified route.', 'Le retour mesuré s’arrête au premier seuil. Aucune mesure ne le prolonge à la seconde porte.', 'The measured return stops at the first threshold. No measurement extends it to the second door.'),
        'repeat-probe': work('secure', 'départ resté fermé', 'departure kept closed', 'Maintenir le premier départ fermé pendant le repérage.', 'Keep the first departure closed during reconnaissance.', 'La seconde sonde du premier trajet reste à faire. Le départ n’a pas été ouvert et la nouvelle porte n’a jamais été vérifiée.', 'The repeat probe of the first route is still to be done. Departure has not been opened, and the new door has never been verified.')
      }),
      crosscheck: work('scan', 'borne du second seuil', 'second-threshold post', 'Tendre un signal de proximité vers la seconde porte.', 'Send a short-range signal toward the second door.', 'La borne proche répond. Rien ne revient de l’autre côté du seuil, malgré sa lumière rassurante.', 'The nearby post answers. Nothing returns from beyond the threshold despite its reassuring light.', 'C’est un mur qui nous dit bienvenue. Je préfère encore un mur honnête.', 'It is a wall telling us welcome. I would rather have an honest wall.'),
      resolution: choose('Où arrêter la ligne ?', 'Where will you stop the line?', {
        apply: answer('Marquer le nouveau seuil comme observé, sans retour connu.', 'Mark the new threshold as observed, with no known return.', 'Le premier trajet garde exactement son état précédent. La seconde porte reçoit son propre avertissement.', 'The first route keeps exactly its previous state. The second door receives its own warning.'),
        hold: answer('Laisser la seconde porte hors du trajet proposé.', 'Leave the second door off the offered route.', 'Le trajet proposé s’arrête à sa dernière limite vérifiée. La nouvelle observation reste à part.', 'The offered route stops at its last verified boundary. The new observation stays separate.'),
        shortcut: answer('Étendre le premier retour à cette porte voisine.', 'Extend the first return to this neighboring door.', '« Tu n’attacherais pas ton harnais à une ombre parce qu’elle touche un mur solide. »', '“You would not clip your harness to a shadow because it touches a solid wall.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('beacon', 'avertissement du second seuil', 'second-threshold warning', 'Poser un repère distinct devant la porte sans retour.', 'Place a separate marker before the door with no return.', 'Le nouveau repère annonce un seuil sans retour connu. Il ne change pas la fermeture éventuelle du premier trajet.', 'The new marker announces a threshold with no known return. It does not change any closure on the first route.'),
        hold: work('secure', 'arrêt du fil publié', 'offered-line stop', 'Arrêter le fil avant la seconde porte.', 'Stop the line before the second door.', 'Le fil ne propose aucun passage supplémentaire. Le dernier trajet conserve son état précédent et le nouveau seuil reste à part.', 'The line offers no additional passage. The last route keeps its previous state, and the new threshold stays separate.')
      }),
      report: say('Revenir à l’ancre en longeant les attaches connues.', 'Return to the anchor alongside the known anchors.', 'Le monde de l’autre côté peut attendre. Ceux de ce côté ont encore besoin d’un retour.', 'The world on the other side can wait. The people on this side still need a way back.')
    }),

  'city-elyra-renewed-passage-v1': quest('arca_elyra',
    ['Cette fois, je veux partir', 'This time, I want to leave'],
    ['Une nouvelle demande arrive à la porte réparée : un passage précis, pour une durée choisie. Elyra veut permettre ce départ sans réveiller les accords que la porte avait appris à réutiliser contre leurs auteurs.', 'A new request reaches the repaired door: one specific passage, for a chosen time. Elyra wants to allow this departure without reviving the agreements the door had learned to reuse against the people who gave them.'],
    ['Je n’ai pas réparé un refus pour enfermer tout le monde. Quelqu’un veut partir cette fois. Aide-moi à garder son oui aussi libre que son non.', 'I did not repair a refusal to lock everyone in. Someone wants to leave this time. Help me keep their yes as free as their no.'],
    ['Quartier Nexus — porte et arrêt Null', 'Nexus district — door and Null stop'], {
      'meet-arca_elyra': say('Rejoindre Elyra près de la nouvelle demande.', 'Join Elyra beside the new request.', 'Ce n’est pas le retour d’un ancien accord. C’est une personne qui choisit maintenant.', 'This is not an old agreement returning. It is a person choosing now.'),
      'inherited-route': fork('byOriginChoice', {
        'honour-both': work('secure', 'mémoire des refus conservés', 'retained-refusal memory', 'Garder les anciens retraits hors de la nouvelle commande.', 'Keep the old withdrawals out of the new control.', 'L’accord ancien et son retrait restent distincts. La nouvelle demande ne réactive aucun des deux.', 'The old agreement and its withdrawal stay distinct. The new request reactivates neither.'),
        'close-terminal': work('scan', 'commande restée fermée', 'control kept closed', 'Lire la nouvelle demande sans rouvrir la porte.', 'Read the new request without reopening the door.', 'La commande est toujours fermée. La demande nouvelle peut être examinée sans réveiller les anciennes permissions.', 'The control is still closed. The new request can be examined without reviving old permissions.')
      }),
      crosscheck: work('repair', 'contact de demande unique', 'single-request contact', 'Raccorder le nouvel accord à son passage et à son arrêt.', 'Connect the new agreement to its passage and its stop.', 'Le volontaire confirme ce passage précis, sa durée et son droit d’arrêter. Le contact reste distinct des anciens accords.', 'The volunteer confirms this specific passage, its duration, and the right to stop. The contact stays separate from old agreements.', 'Il a compris où mène la porte. Il a choisi cette fois. Je veux qu’elle s’en souvienne sans lui voler la prochaine.', 'He knows where the door leads. He chose this time. I want it to remember that without stealing his next choice.'),
      resolution: choose('Comment répondre à ce départ ?', 'How will you answer this departure?', {
        apply: answer('Armer ce seul passage en gardant l’arrêt à portée.', 'Arm this passage alone while keeping the stop within reach.', 'Elyra accepte un accord limité et révocable. La commande finale doit rester liée à cette demande seule.', 'Elyra accepts limited, revocable agreement. The final control must stay tied to this request alone.'),
        hold: answer('Laisser la porte fermée le temps d’une dernière confirmation.', 'Leave the door closed for one last confirmation.', 'Le départ attendra. Aucun ancien oui ne sera utilisé pour combler cette attente.', 'Departure will wait. No old yes will be used to fill that wait.'),
        shortcut: answer('Réactiver tous les anciens accords pour les prochains départs.', 'Reactivate all old agreements for the next departures.', '« Un oui n’efface pas tous les non qu’on a prononcés avant. »', '“One yes does not erase every no spoken before it.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('route', 'commande du passage choisi', 'chosen-passage control', 'Armer la commande limitée et garder l’arrêt Null actif.', 'Arm the limited control and keep the Null stop active.', 'La commande répond uniquement à cette demande. L’arrêt reste actif et les anciens accords restent retirés.', 'The control answers only this request. The stop stays active, and the old agreements remain withdrawn.'),
        hold: work('secure', 'verrou d’attente de la porte', 'door waiting lock', 'Verrouiller la porte en laissant la nouvelle demande accessible.', 'Lock the door while leaving the new request accessible.', 'La porte attend la confirmation. La nouvelle demande reste lisible sans rouvrir une ancienne permission.', 'The door awaits confirmation. The new request remains readable without reopening an old permission.')
      }),
      report: say('Revenir à l’ancre sans retirer la commande d’arrêt.', 'Return to the anchor without removing the stop control.', 'Partir ou rester. Ce n’est pas à la machine de rendre l’un de ces mots impossible.', 'Leave or stay. It is not for the machine to make either word impossible.')
    }),

  'city-oryn-manifest-delivery-v1': quest('arca_oryn',
    ['La voix qui voulait se taire', 'The voice that wanted silence'],
    ['Un vieux relais d’accueil garde un lien vers la contribution retirée d’un témoin de Route X. Même si l’appel principal est arrêté, ce raccord pourrait rediffuser sa voix. Oryn veut retrouver et couper cette fuite.', 'An old reception relay keeps a link to a Route X witness’s withdrawn contribution. Even if the main call is stopped, this connection could broadcast their voice again. Oryn wants to find and cut the leak.'],
    ['Il nous a demandé de ne plus faire entendre cette phrase. Il ne devrait pas avoir à le répéter à chaque machine de la Cité. Viens, on suit le fil jusqu’au bout.', 'He asked us to stop playing that sentence. He should not have to repeat it to every machine in the City. Come on. We will follow the wire to the end.'],
    ['Quartier Nexus — relais public du point d’accueil', 'Nexus district — reception public relay'], {
      'meet-arca_oryn': say('Retrouver Oryn avant le relais public.', 'Meet Oryn before the public relay.', 'Rendre une voix, c’est aussi lui rendre le droit de se taire.', 'Giving a voice back also means giving it back the right to be silent.'),
      'inherited-route': fork('byOriginChoice', {
        'separate-voices': work('scan', 'relais des voix séparées', 'separate-voice relay', 'Suivre les fils des contributions restées autorisées.', 'Follow the wires of the contributions still authorized.', 'Les signatures restent distinctes. Le retrait doit encore être respecté dans le vieux raccord de l’accueil.', 'The signatures stay distinct. Withdrawal must still be respected in reception’s old connection.'),
        'hold-attribution': work('secure', 'appel resté en attente', 'call kept on hold', 'Garder l’appel suspendu pendant la recherche de la fuite.', 'Keep the call suspended while tracing the leak.', 'L’appel est toujours en attente d’une relecture volontaire. Aucun nom n’a été ajouté à la place des témoins.', 'The call is still awaiting voluntary review. No name has been inserted in the witnesses’ place.')
      }),
      crosscheck: work('scan', 'ancien raccord de diffusion', 'old broadcast connection', 'Retrouver le raccord qui vise encore la voix retirée.', 'Find the connection still pointing to the withdrawn voice.', 'Le vieux raccord mentionne le retrait mais pointe toujours vers la phrase. Il pourrait la rediffuser malgré le choix du témoin.', 'The old connection mentions the withdrawal but still points to the sentence. It could replay it despite the witness’s choice.', 'C’est là. Ce petit fil aurait suffi à parler encore à sa place.', 'There. That small wire would have been enough to speak for him again.'),
      resolution: choose('Comment arrêter cette fuite ?', 'How will you stop this leak?', {
        apply: answer('Retirer le lien de la voix et garder la trace de son retrait.', 'Remove the voice link and keep the record of its withdrawal.', 'Oryn choisit de couper cette diffusion précise. Le témoin garde sa place sans que sa phrase reste publique.', 'Oryn chooses to cut this specific broadcast. The witness keeps their place without the sentence staying public.'),
        hold: answer('Couper la copie d’accueil entière pour une relecture volontaire.', 'Disconnect the entire reception copy for voluntary review.', 'La copie doit rester silencieuse pendant la relecture. Les voix ne seront ni fusionnées ni réattribuées.', 'The copy must stay silent during review. The voices will be neither merged nor reassigned.'),
        shortcut: answer('Diffuser la phrase sous le nom d’Oryn.', 'Broadcast the sentence under Oryn’s name.', '« Lui voler sa signature ne nous rend pas sa permission. »', '“Stealing his signature does not give us his permission back.”')
      }),
      'verify-intervention': fork('byChoice', {
        apply: work('repair', 'sortie de la voix retirée', 'withdrawn-voice output', 'Débrancher le lien public et isoler son ancienne prise.', 'Disconnect the public link and isolate its old socket.', 'La phrase n’est plus reliée à la sortie publique. La trace du retrait reste visible et les autres voix gardent leurs propres noms.', 'The sentence is no longer linked to public output. The withdrawal remains visible, and the other voices keep their own names.'),
        hold: work('secure', 'coupe-circuit de la copie d’accueil', 'reception-copy cutout', 'Couper la copie d’accueil sans effacer les voix séparées.', 'Disconnect the reception copy without erasing the separate voices.', 'La copie d’accueil reste hors diffusion. Les contributions attendent leur relecture sans devenir une voix collective.', 'The reception copy stays off air. The contributions await review without becoming one collective voice.')
      }),
      report: say('Revenir à l’ancre après avoir suivi le fil jusqu’à sa sortie.', 'Return to the anchor after following the wire to its output.', 'Il pourra revenir parler. Quand il le voudra. Et ce sera encore sa voix.', 'He can come back and speak. When he wants to. And it will still be his voice.')
    }, ['src/game/ocCampaign.js#8807'])
});
